INSERT INTO settings (key, value, updatedAt) VALUES ('aboutHeroTitle', 'حول TRQ', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutHeroDescription', 'We are a luxury interior design studio dedicated to creating timeless, sophisticated spaces that reflect our clients'' refined taste and elevated lifestyle.', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutHeroImage', '/uploads/14.webp', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutVisionTitle', 'رؤيتنا', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutVisionDescription', 'إعادة تعريف الحياة الفاخرة من خلال التصميم المدروس الذي يتجاوز الاتجاهات ويخلق جمالاً دائماً. نؤمن بمساحات تحكي القصص وتثير المشاعر وتصمد أمام اختبار الزمن.', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutMissionTitle', 'مهمتنا', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutMissionDescription', 'نخدم العملاء المميزين بتحويل مساحاتهم إلى ملاذات شخصية من الأناقة والوظيفة. من خلال الاهتمام الدقيق بالتفاصيل والشراكة التعاونية نقدم ديكورات داخلية تتجاوز التوقعات.', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproachTitle', 'نهجنا', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproachDescription', 'كيف نحقق رؤيتك', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach1Title', 'التوجيه المدروس', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach1Description', 'Every design decision is purposeful, guided by deep understanding of our clients'' lifestyle and aesthetic preferences.', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach1Icon', 'Compass', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach2Title', 'التميز المتعدد الطبقات', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach2Description', 'نبني التعقيد من خلال الطبقات الحذرة للنسيج والمواد والعناصر التي تخلق العمق والاهتمام البصري.', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach2Icon', 'Layers', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach3Title', 'الجودة الخالدة', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach3Description', 'نعطي الأولوية للجمال الدائم على الاتجاهات العابرة واختيار المواد والتشطيبات التي تتقدم بأناقة.', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach3Icon', 'Star', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach4Title', 'الشراكة التعاونية', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach4Description', 'نعمل بشكل وثيق مع العملاء كشركاء إبداعيين مما يضمن أن كل مساحة تعكس بصدق رؤيتهم واحتياجاتهم.', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutApproach4Icon', 'Users', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutExpertiseTitle', 'خبرتنا', '2026-02-28 00:42:27');
