INSERT INTO settings (key, value, updatedAt) VALUES ('aboutExpertise1Title', 'السكنية الفاخرة', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutExpertise1Description', 'المنازل الخاصة والعقارات المصممة بعناية لا تتزعزع للراحة والأناقة والتعبير الشخصي.', '2026-02-28 00:42:27');
