INSERT INTO settings (key, value, updatedAt) VALUES ('aboutExpertise2Description', 'البيئات المهنية التي تجسد هوية العلامة التجارية مع إنشاء مساحات ملهمة للعمل والتعاون.', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutExpertise2Image', '/uploads/2.webp', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutExpertise3Title', 'الأثاث المخصص', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutExpertise3Description', 'القطع المصممة والمصنوعة بشكل مخصص لتكمل كل مساحة بشكل مثالي وتعكس تفضيلات النمط الفردية.', '2026-02-28 00:42:27');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutExpertise3Image', '/uploads/14.webp', '2026-02-28 00:42:27');
