INSERT INTO settings (key, value, updatedAt) VALUES ('aboutWhoWeArePara2', 'The studio delivers fully integrated design solutions that respect context and identity, executed to the highest standards across high-end residential, commercial, and distinguished institutional projects.', '2026-02-28 00:42:30');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutWhoWeArePara3', 'We create lasting design solutions that reflect your vision and enhance the way you live and work through a combination of artistic vision and practical expertise.', '2026-02-28 00:42:30');
