INSERT INTO settings (key, value, updatedAt) VALUES ('aboutStoryText1_ar', 'تأسست بشغف لإنشاء مساحات استثنائية، ظهرت TRQ من الاعتقاد بأن التصميم الرائع له القوة على تحويل ليس فقط الغرف، بل الحياة.', '2026-02-28 01:10:51');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutStoryText2_ar', 'بدأت رحلتنا بفلسفة بسيطة: الفخامة ليست عن الإفراط، بل عن التحسين. كل مشروع نتولاه هو فرصة لدفع الحدود الإبداعية مع احترام مبادئ التصميم الخالد.', '2026-02-28 01:10:51');
INSERT INTO settings (key, value, updatedAt) VALUES ('aboutStoryText3_ar', 'اليوم، نستمر في التطور، ونسعى دائماً إلى طرق جديدة لإنشاء مساحات تلهم وتستمر.', '2026-02-28 01:10:51');
