INSERT INTO settings (key, value, updatedAt) VALUES ('servicesDescription_ar', 'من المساحات السكنية الحميمة إلى المشاريع التجارية الكبرى، من أجنحة المعارض إلى الأثاث المخصص، يقدم TRQ مجموعة شاملة من خدمات التصميم. يضمن نهجنا متعدد التخصصات التكامل السلس عبر جميع جوانب مشروعك، مما يوفر نتائج متماسكة واستثنائية.', '2026-02-28 01:10:51');
