INSERT INTO settings (key, value, updatedAt) VALUES ('workflowTimelineParagraph1_ar', 'بينما كل مشروع فريد، تتبع معظم المشاريع جدولاً زمنياً مماثلاً. عادة ما تستغرق المشاريع السكنية 3-6 أشهر من المفهوم إلى الإنجاز، بينما قد تتطلب المشاريع التجارية الأكبر 6-12 شهراً أو أكثر. عادة ما يكون لتصاميم أكشاك المعارض أوقات تسليم أسرع من 2-6 أسابيع حسب التعقيد', '2026-02-28 01:10:52');
